.hero__featured {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 1.25rem 1.75rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.hero__featured-item {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 1 calc(50% - 1.75rem);
}

.hero__logo {
  display: block;
  width: auto;
  height: auto;
  max-width: 7.5rem;
  max-height: 2.25rem;
  object-fit: contain;
}

@media screen and (min-width: 48em) {
  .hero__featured {
    justify-content: center;
    gap: 1.5rem 2rem;
  }

  .hero__featured-item {
    flex: 0 1 calc(33.333% - 2rem);
  }

  .hero__logo {
    max-width: 8.75rem;
    max-height: 2.75rem;
  }
}

@media screen and (min-width: 80em) {
  .hero__featured-item {
    flex: 0 1 calc(25% - 2rem);
  }
}		</style>
